#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-05
"""Cost of the fishwait24 state-link probes from a scripts/state_probe_campaign.sh campaign.

Reads <log_dir>/night_runs.txt ("<config>_<pass> <campaign dir> …"), takes Autoware's own measurements and the CPU
sampler of every run (same extraction as analyze_overhead_modes.py) and prints, per metric, mean ± std over the
passes for each configuration, the change against the untraced baseline and against `off` (FISH without the new
events), and the PAIRED change against `off` (same pass, so slow drift of the host cancels).

usage: state_probe_overhead.py <log_dir> [--json out.json]
"""
import json, os, re, statistics as st, subprocess, sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'autoware_runs'))
from analyze_overhead import analyze_side  # noqa: E402

ROWS = [
    ("app-set CPU [cores, busiest 60 s]", "cpu_app_peak60"),
    ("observer-set CPU [cores]", "cpu_obs_peak60"),
    ("chain latency [ms]", "chain_latency_ms"),
    ("Total Latency [ms]", "total_latency_ms"),
    ("concat processing [ms]", "concat_proc_ms"),
    ("centerpoint proc [ms]", "centerpoint_proc_ms"),
    ("multi_object_tracker [ms]", "mot_latency_ms"),
    ("objects rate [Hz]", "rate_objects"),
    ("obstacle pc rate [Hz]", "rate_obstacle_pc"),
    ("UST trace size [MB]", "trace_mb"),
]
ORDER = ["base", "off", "s123", "s123A", "all"]

def main():
    ld = sys.argv[1]
    runs = {}                                     # config -> pass -> metrics
    desk_max = float(os.environ.get('NIGHT_RUNS_DESK_MAX', '0.8')); excluded = []
    for line in open(os.path.join(ld, 'night_runs.txt')):
        m = re.match(r'(\w+?)_(\d+) (\S+)', line)
        if not m:
            continue
        cfg, p, d = m.group(1), int(m.group(2)), m.group(3)
        # validity gates logged by night_runs.sh: thermal throttle events and desktop load during the run
        thr = re.search(r'thr=\+(-?\d+)', line); desk = re.search(r'desk=([0-9.]+)', line)
        if (thr and int(thr.group(1)) > 0) or (desk and float(desk.group(1)) > desk_max):
            excluded.append(f"{cfg}_{p} ({'thr=+' + thr.group(1) if thr else ''} {'desk=' + desk.group(1) if desk else ''})")
            continue
        rd = os.path.join(d, 'baseline_1' if cfg == 'base' else 'nsys_1')
        try:
            s = analyze_side(rd)
        except Exception as e:
            print(f"[warn] {cfg}_{p} {rd}: {e}", file=sys.stderr); continue
        sf = os.path.join(rd, 'session.txt')
        if os.path.exists(sf):
            sd = os.path.join(os.path.expanduser('~/fish_traces'), os.path.basename(open(sf).read().strip()), 'ros2')
            if os.path.isdir(sd):
                s['trace_mb'] = int(subprocess.run(['du', '-sm', sd], capture_output=True, text=True).stdout.split()[0])
                s['session'] = os.path.basename(os.path.dirname(sd))
        runs.setdefault(cfg, {})[p] = s
    cfgs = [c for c in ORDER if c in runs] + [c for c in runs if c not in ORDER]
    print(f"# state-link probes: cost — {ld}  (passes: " + ', '.join(f"{c}={len(runs[c])}" for c in cfgs) + ")\n")
    if excluded:
        print(f"excluded (throttled, or desktop above {desk_max} busy cores): " + ', '.join(excluded) + "\n")
    def ms(vals):
        return (st.mean(vals), st.stdev(vals) if len(vals) > 1 else 0.0) if vals else (None, None)
    out = {}
    print("| metric | " + " | ".join(cfgs) + " |")
    print("|---|" + "--:|" * len(cfgs))
    for label, key in ROWS:
        cells = []
        for c in cfgs:
            m, s = ms([r[key] for r in runs[c].values() if r.get(key) is not None])
            cells.append("—" if m is None else f"{m:.2f}±{s:.2f}")
            out.setdefault(key, {})[c] = dict(mean=m, std=s, values={p: r.get(key) for p, r in runs[c].items()})
        print(f"| {label} | " + " | ".join(cells) + " |")
    for ref in ("base", "off"):
        if ref not in runs:
            continue
        print(f"\n## change against `{ref}` (mean of configuration / mean of {ref})\n")
        print("| metric | " + " | ".join(c for c in cfgs if c != ref) + " |")
        print("|---|" + "--:|" * (len(cfgs) - 1))
        for label, key in ROWS:
            b, _ = ms([r[key] for r in runs[ref].values() if r.get(key) is not None])
            cells = []
            for c in cfgs:
                if c == ref:
                    continue
                m, _ = ms([r[key] for r in runs[c].values() if r.get(key) is not None])
                cells.append("—" if m is None or not b else f"{(m - b) / b * 100:+.2f}%")
            print(f"| {label} | " + " | ".join(cells) + " |")
    if "off" in runs:
        print("\n## paired change against `off` of the same pass (mean ± std of the per-pass differences, in % of `off`)\n")
        print("| metric | " + " | ".join(c for c in cfgs if c not in ("off", "base")) + " |")
        print("|---|" + "--:|" * (len([c for c in cfgs if c not in ("off", "base")])))
        for label, key in ROWS:
            cells = []
            for c in cfgs:
                if c in ("off", "base"):
                    continue
                d = [(runs[c][p][key] - runs["off"][p][key]) / runs["off"][p][key] * 100 for p in runs[c]
                     if p in runs["off"] and runs[c][p].get(key) is not None and runs["off"][p].get(key)]
                m, s = ms(d)
                cells.append("—" if m is None else f"{m:+.2f}±{s:.2f}%")
                out[key].setdefault('paired_vs_off', {})[c] = dict(mean=m, std=s, n=len(d))
            print(f"| {label} | " + " | ".join(cells) + " |")
    print("\nsessions: " + '; '.join(f"{c}: " + ' '.join(r.get('session', '-') for _, r in sorted(runs[c].items())) for c in cfgs if c != 'base'))
    if '--json' in sys.argv:
        json.dump(out, open(sys.argv[sys.argv.index('--json') + 1], 'w'), indent=1)

if __name__ == '__main__':
    main()
